SOKAI_L.SUST = [{"z":"舟","e":"barca","l":["zhōu","shū","ju"],"q":"O círculo, as ovais, as amêndoas, as cápsulas, os losangos e os retângulos: cascos de barca.","n":"A barca: a de Zhuangzi, a do pescador solitário, a do monge que atravessa o rio."},{"z":"峽","e":"estreito","l":["xiá","kyō","hyeop"],"q":"Duas terras unidas por uma passagem.","n":"O estreito ou desfiladeiro, como as Três Gargantas (三峽) do Yangtzé."},{"z":"華","e":"flor","l":["huá","ka","hwa"],"q":"Flores, estrelas e trevos de quatro lóbulos.","n":"A flor: 華嚴 (Huayan, Hwaeom, Kegon), a escola da Guirlanda de Flores do budismo na China, na Coreia e no Japão."},{"z":"道","e":"caminho","l":["dào","dō","do"],"q":"Cruzes, aspas e traços: a terra escreve 十, 米, 田, 王, 中.","n":"O Caminho: o Tao. Dào em chinês, dō em japonês, do em coreano."},{"z":"井","e":"poço","l":["jǐng","sei","jeong"],"q":"Quatro poços de um ponto. Em E1, o octógono.","n":"O poço: 井 é também o campo dividido em nove partes da China antiga."},{"z":"泉","e":"fonte","l":["quán","sen","cheon"],"q":"Oito fontes de um ponto.","n":"A fonte, a origem."},{"z":"潭","e":"pego","l":["tán","tan","dam"],"q":"Poços nos eixos e nas diagonais ao mesmo tempo.","n":"O pego fundo e calmo onde, dizem os contos, dorme um dragão."},{"z":"池","e":"lagoa","l":["chí","chi","ji"],"q":"Lagoas de dois, três e quatro pontos.","n":"A lagoa do jardim e do templo."},{"z":"湖","e":"lago","l":["hú","ko","ho"],"q":"Lagos em cruz e em barreira.","n":"O lago, como o lago do Oeste (西湖) de Hangzhou."},{"z":"海","e":"mar","l":["hǎi","kai","hae"],"q":"Os maiores lagos: mares no interior da terra.","n":"O mar. É a coluna central do tabuleiro: K10 é 滄海, Sokai."},{"z":"田","e":"campo","l":["tián","den","jeon"],"q":"Campos quadrados separados por rios com vaus.","n":"O campo cultivado."},{"z":"川","e":"rio","l":["chuān","sen","cheon"],"q":"Rios na diagonal.","n":"O rio."},{"z":"津","e":"vau","l":["jīn","shin","jin"],"q":"Ilhas e pequenos campos entre canais, cheios de passagens.","n":"O vau, a passagem do rio. 問津, «perguntar pelo vau», significa nos Analectos procurar o caminho."},{"z":"灣","e":"baía","l":["wān","wan","man"],"q":"Quatro baías que entram na terra.","n":"A baía."},{"z":"浦","e":"enseada","l":["pǔ","ho","po"],"q":"Oito baías e tridentes.","n":"A enseada: o -po dos portos coreanos e o -ura dos japoneses."},{"z":"島","e":"ilha","l":["dǎo","tō","do"],"q":"Uma ilha redonda ou em losango no meio de um anel de terra.","n":"A ilha."},{"z":"城","e":"castelo","l":["chéng","jō","seong"],"q":"Uma ilha quadrada ou octogonal com o seu fosso: um castelo. Em R1, as quatro portas.","n":"O castelo e a cidade amuralhada: a Grande Muralha (長城), Himeji (姫路城), Hwaseong (華城)."},{"z":"輪","e":"roda","l":["lún","rin","ryun"],"q":"Uma ilha e dois anéis: ondas na água.","n":"A roda: 法輪, a roda do Dharma."},{"z":"巖","e":"rocha","l":["yán","gan","am"],"q":"Rochas soltas em ordem, como num jardim de pedras.","n":"A escarpa, a rocha: o jardim seco (枯山水) dos templos zen."}];
